SELECT COUNT(*) OVER() AS TOTAL_RECORD_COUNT, TB.* FROM ( SELECT CL_CODE, CL_CODE_NM, USE_AT, TO_CHAR(LAST_UPDT_PNTTM, 'YYYY-MM-DD HH24:MI') AS LAST_UPDT_PNTTM, LAST_UPDUSR_ID, CL_CODE_DC FROM COMTCCMMNCLCODE a WHERE 1=1
AND a.CL_CODE LIKE CONCAT('%', #{params.searchKeyword}, '%')
AND a.CL_CODE_NM LIKE CONCAT('%', #{params.searchKeyword}, '%')
AND a.USE_AT = #{params.useYn}
ORDER BY a.LAST_UPDT_PNTTM DESC ) TB LIMIT #{params.recordCountPerPage} OFFSET #{params.firstIndex}

SELECT CL_CODE as clCode, CL_CODE_NM clCodeNm, USE_AT useAt, CL_CODE_DC clCodeDc, FRST_REGISTER_ID frstRegisterId
FROM COMTCCMMNCLCODE
WHERE CL_CODE = #{clCode}

